import { defineStore } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import { convertAmountService } from 'src/services';
import { useWebSocketStore } from 'src/store/main';
import { isEmptyString, isUndefinedOrNull } from 'src/utils/general';

// Values waiting for the next flush, keyed by cache key so duplicates collapse.
// Module scope, not state: these are in-flight bookkeeping, not data to render.
const pendingFormats = new Map<
  string,
  { value: any; source_locale: string; dest_locale: string }
>();
let pendingFlush: Promise<void> | null = null;

// source_locale belongs in the key: the same value string converted FROM a
// different locale is a different number ('1.000,50' is 1000.5 from de_DE,
// 1.0005 from en_US). A caller that omits it just misses the cache and refetches.
export function amountCacheKey(
  value: any,
  source_locale: string,
  dest_locale: string,
): string {
  return `${value}_${source_locale}_${dest_locale}`;
}

export const useAmountFormatStore = defineStore('amount_format', {
  state: () => ({
    convertion_amount_cache: {} as dynamicObj,
    websocket_store: useWebSocketStore(),
  }),
  getters: {},
  actions: {
    getRequestValues(values: any, dest_locale: string, source_locale = '') {
      const cached_values = [] as dynamicObj[];
      for (const [index, item] of values.entries()) {
        cached_values.push({
          key: item.key,
          value:
            this.convertion_amount_cache[
              amountCacheKey(item.key, source_locale, dest_locale)
            ],
        });
      }

      return cached_values;
    },

    // TODO:: check values too from cache
    async formatMultiValues(
      values: any,
      source_locale = '',
      dest_locale = 'en_US',
    ) {
      try {
        let response = {} as dynamicObj | undefined;
        const notCachedValues = values.filter((item: dynamicObj) => {
          return !this.hasConvertedAmountInCache(
            item.key,
            dest_locale,
            source_locale,
          );
        });

        // make call to server
        if (notCachedValues.length > 0) {
          if (this.websocket_store.isConnected) {
            response = await this.sendWebSocketMessage({
              values: notCachedValues,
              source_locale,
              dest_locale,
            });
          } else {
            response = await convertAmountService.convertMultiValuesAsLocale(
              notCachedValues,
              source_locale,
              dest_locale,
            );
          }

          if (!response || !response.success) {
            throw response;
          }

          this.addValuesToCache(response.data.values, dest_locale, source_locale);
        }

        const result = this.getRequestValues(values, dest_locale, source_locale);
        return result;
      } catch (err) {
        logError(err);
        return [] as dynamicObj[];
      }
    },

    async sendWebSocketMessage(data: dynamicObj) {
      const response = await this.websocket_store.send('calculation', data);
      return response;
    },

    addValuesToCache(values: any, target_locale: string, source_locale = '') {
      Array.from(values).forEach((row: any, index: any) => {
        let dest_locale = target_locale;
        if (row.hasOwnProperty('dest_locale')) {
          dest_locale = row.dest_locale;
        }
        this.convertion_amount_cache[
          amountCacheKey(row.key, source_locale, dest_locale)
        ] = row.value;
      });
    },

    hasConvertedAmountInCache(
      value: any,
      target_locale: string,
      source_locale = '',
    ) {
      return this.convertion_amount_cache.hasOwnProperty(
        amountCacheKey(value, source_locale, target_locale),
      );
    },

    /**
     * Formatting one value, but every call made in the same tick is answered by a
     * single /format_amounts request: a form with twenty amount fields used to fire
     * twenty /format_amount calls.
     */
    async formatValue(
      value: any,
      source_locale: string,
      dest_locale = 'en_US',
    ) {
      try {
        if (this.hasConvertedAmountInCache(value, dest_locale, source_locale)) {
          return this.convertion_amount_cache[
            amountCacheKey(value, source_locale, dest_locale)
          ] as string;
        }

        if (isUndefinedOrNull(value) || isEmptyString(value)) {
          value = '0';
        }

        const cache_key = amountCacheKey(value, source_locale, dest_locale);
        pendingFormats.set(cache_key, { value, source_locale, dest_locale });

        if (!pendingFlush) {
          pendingFlush = Promise.resolve().then(() => this.flushPendingFormats());
        }
        await pendingFlush;

        if (!this.hasConvertedAmountInCache(value, dest_locale, source_locale)) {
          throw new Error('amount formatting returned no value for ' + cache_key);
        }
        return this.convertion_amount_cache[cache_key] as string;
      } catch (err) {
        logError(err);
        return '0.00';
      }
    },

    async flushPendingFormats() {
      const batch = Array.from(pendingFormats.values());
      pendingFormats.clear();
      // Cleared before awaiting, so calls arriving during the request form the next batch.
      pendingFlush = null;

      const groups = new Map<string, dynamicObj[]>();
      for (const item of batch) {
        const group_key = item.source_locale + '|' + item.dest_locale;
        const group = groups.get(group_key) ?? [];
        group.push({ key: item.value, value: item.value });
        groups.set(group_key, group);
      }

      for (const [group_key, values] of groups) {
        const [source_locale, dest_locale] = group_key.split('|');
        await this.formatMultiValues(values, source_locale, dest_locale);
      }
    },

    resetStore() {
      this.convertion_amount_cache = {} as dynamicObj;
      pendingFormats.clear();
      pendingFlush = null;
    },

    searchValueByKey(key: string, arrayOfObjects: dynamicObj[]) {
      const foundObject = arrayOfObjects.find((obj) => obj.key === key);
      if (!foundObject) {
        return '';
      }

      return foundObject.value as string;
    },
  },
});
