/**
 * Strips markup out of a translated string so it can be shown as text.
 *
 * DOCB-14036: `layout_template_id_not_found` ships an `<a href='{{url}}'>` in
 * every locale (several of them with malformed quoting). Toast titles are
 * rendered as text by vue-sonner, so that anchor reached the user verbatim.
 * Rather than opening a toast up to HTML — the same call site also carries
 * backend-supplied error text, which must never be an HTML sink — the markup is
 * dropped here and the link is offered as a real toast action instead.
 */
function toPlainText(message: string): string {
  return message
    .replace(/<[^>]*>/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

