// True when the auth server rejected the credentials (HTTP 400/401 with an
// OAuth2 error of invalid_request/invalid_grant/invalid_credentials, or an
// empty body). Transport failures — no response, or 5xx — return false.
export function isRetryableRegionLoginError(error: unknown): boolean {
  const response = (error as { response?: { status?: number; data?: unknown } })
    ?.response;
  const status = response?.status;
  if (status !== 400 && status !== 401) {
    return false;
  }
  const oauthError = (response?.data as { error?: string } | undefined)?.error;
  return (
    oauthError === undefined ||
    oauthError === 'invalid_request' ||
    oauthError === 'invalid_grant' ||
    oauthError === 'invalid_credentials'
  );
}

// Of two rejected-login errors, pick the one whose response body carries a
// specific `error_code` (e.g. NO_ORGANISATION). A coded error is a definitive
// account-status answer and is more informative than a bare
// invalid_request/invalid_grant. Falls back to `primary` when neither (or both)
// carry a code.
export function preferErrorWithCode<T>(primary: T, secondary: T): T {
  const codeOf = (e: unknown): string | undefined =>
    (
      (e as { response?: { data?: { error_code?: string } } })?.response?.data ??
      undefined
    )?.error_code;
  if (!codeOf(primary) && codeOf(secondary)) {
    return secondary;
  }
  return primary;
}

