  public async login(
    data: loginRequest,
    authRegion?: ApiRegion,
  ): Promise<any> {
    // OAuth2 requires application/x-www-form-urlencoded, not multipart/form-data
    // We use direct axios call to bypass org_id injection from AbstractApiService
    const urlParams = new URLSearchParams();
    for (const [key, value] of Object.entries(data)) {
      urlParams.append(key, value);
    }
    urlParams.append('grant_type', 'password');
    // Request offline_access scope to receive refresh_token for long-running tasks (DOCB-9171)
    urlParams.append('scope', 'profile offline_access');
    // ✅ RFC 6749 Compliance: Add client_id for public client authentication
    urlParams.append('client_id', 'frontend');

    const tokenUrl = authRegion
      ? buildAuthUrl(authRegion) + '/v2/oauth2/token'
      : api.get_token;

    try {
      console.log('[LOGIN] 🔹 Calling token endpoint:', tokenUrl);
      const response = await this.client.post(tokenUrl, urlParams, {
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          // RFC 6749: Public client authentication uses client_id parameter only (line 111)
          // Do NOT include Authorization header for public clients
        },
        timeout: 10000,
      });

      console.log('[LOGIN] ✅ Token endpoint response:', response.status, response.data);
      return this.handleResponse(response);
    } catch (error: any) {
      console.error('[LOGIN] ❌ Token endpoint failed:', error.message, error.response?.status, error.response?.data);
      this.handleAPILoginError(error);
      throw error;
    }
  }

  // DOCB-13743: second-factor verification at login. Unauthenticated (no full
  // token exists yet) — carries the short-lived mfa_token, like login() it uses
  // the raw client to bypass org_id/auth injection. On success the response is
  // either a full token pair or an org_selection payload; on failure a
  // { error_code } body (4xx/429), which handleResponse surfaces as an error.
  private async _verifyMfa(
    path: string,
    mfaToken: string,
    code: string,
    authRegion?: ApiRegion,
    rememberDevice = false,
  ): Promise<any> {
    const url = (authRegion ? buildAuthUrl(authRegion) : buildAuthUrl()) + path;
    const response = await this.client.post(
      url,
      { mfa_token: mfaToken, code, remember_device: rememberDevice },
      // withCredentials so the server can set the httpOnly trusted-device cookie
      // (DOCB-13744) when remember_device is true.
      {
        headers: { 'Content-Type': 'application/json' },
        timeout: 10000,
        withCredentials: true,
      },
    );
    return this.handleResponse(response);
  }

