  handleAPILoginError(error: unknown): any {
    if (error instanceof Error && error.message.includes('timeout')) {
      throw {
        message: 'Request is taking time, Please try again after few seconds',
      };
    }

    if (error instanceof Error && error.message == 'Network Error') {
      throw { message: 'network_error' };
    }

    throw error;
  }

  // DOCB-13989 round 2: `authRegion`, when given, targets the profile probe
  // at that SPECIFIC region's auth host (mirrors login()'s per-call
  // buildAuthUrl(authRegion)) instead of the module-load-time-frozen
  // `api.get_profile` host. This matters for the pre-reload region-mismatch
  // detection in PrepareDashboard.detectAndStartRegionSwitch(): on a fresh
  // session `api.get_profile`'s AUTH_URL is baked in from getCurrentAuthRegion()
  // as it stood at the FIRST module load (before the user ever touched the
  // login region dropdown), so a login on the non-default region left the
  // probe silently querying the WRONG auth cluster relative to where the
  // just-issued token actually came from — a same-region 401 with no chance
  // to ever become a 200, immediately swallowed into `{}` by the catch below,
  // so the caller always saw "no organisations" and never detected the real
  // mismatch. Omit authRegion to keep the frozen-host default for every other
  // caller (dashboard, settings, …) where the frozen constant is correct
  // because it was never subject to an in-session region pick.
  public async getProfile(authRegion?: ApiRegion): Promise<any> {
    const url = authRegion
      ? buildAuthUrl(authRegion) + '/v2/oauth2/profile'
      : api.get_profile;
    try {
      return await super.get(url);
    } catch (error: any) {
      // ✅ CRITICAL FIX: Don't trigger token refresh on profile 401 errors
      // Profile endpoint may return 401 for various reasons (auth service sync, org_id issues)
      // This should NOT show misleading "Session expired" message
      // Instead, return empty profile to allow dashboard to load with degraded functionality
      if (error?.response?.status === 401) {
        logger.warn(
          '[PROFILE] GET /users/profile returned 401. Profile unavailable but app can continue with limited functionality.',
        );
        return {}; // Return empty profile instead of triggering logout
      }
      throw error; // Re-throw other errors
    }
  }

  public async getOrgPreferences(): Promise<any> {
    return this.dedupeGetRequest('getOrgPreferences', async () => {
      try {
        // NOTE: intentionally still the full untyped GET /preferences/get_preferences
        // (not the typed GET /preferences/settings) — that typed endpoint strips
        // large blob keys (AI_SYSTEM_PROMPT, AI_ASSISTANT_PROMPT, EDI_*, PREVIEW)
        // that Settings/Components/AiPrompt/{System,Assistant}.vue read directly
        // from user_settings/org_based_settings. Boolean correctness here is
        // handled at the read site via toBoolPreference() (src/utils/preferenceBool.ts),
        // which is kept in lockstep with the backend's falsy-string set — see
        // Groups.vue / Groups_deprecated.vue.
        return await super.get(api.get_preferences);
      } catch (error: any) {
        // ✅ CRITICAL FIX: Don't trigger token refresh on preferences 401 errors
        // Preferences endpoint may return 401 for various reasons (service issues, org_id sync timing)
        // This should NOT cause app-wide reload or token refresh attempts
        if (error?.response?.status === 401) {
          logger.warn(
            '[PREFERENCES] GET /preferences/get_preferences returned 401. Preferences unavailable but app can continue with defaults.',
          );
          return {}; // Return empty preferences instead of propagating error
        }
        throw error; // Re-throw other errors
      }
    });
  }

