import { api, getAuthorizationToken } from 'pages/APIs';
import AbstractApiService from 'src/services/abstractApiService';
import type { dynamicObj } from 'src/pages/assets';

export default class FormBuilderApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  public async loadDocumentDefaultFields(doc_type: string): Promise<any> {
    const data = {
      params: {
        doc_type: doc_type,
        profile: 'DEFAULT',
      },
    };
    return super.get(api.get_field_settings_by_type, data);
  }

  public async getLayoutTemplates(queries: dynamicObj): Promise<any> {
    let querystring = '';
    if (Object.keys(queries).length !== 0) {
      querystring += '?';
      querystring += this.encodeQueryData(queries);
    }

    return super.get(api.get_layout_templates + querystring, {});
  }

  public async getAllLayoutTemplates(queries: dynamicObj): Promise<any> {
    let querystring = '';
    if (Object.keys(queries).length !== 0) {
      querystring += '?';
      querystring += this.encodeQueryData(queries);
    }

    return super.get(api.get_all_layout_templates + querystring, {});
  }

  public async resolveDocumentLayout(queries: dynamicObj): Promise<any> {
    let querystring = '';
    if (Object.keys(queries).length !== 0) {
      querystring += '?';
      querystring += this.encodeQueryData(queries);
    }

    return super.get(api.resolve_document_layout + querystring, {});
  }

  public async getLayoutTemplateId(layoutId: string): Promise<any> {
    return super.get(api.document_layout_template_by_id + layoutId, {});
  }

  public async getDocumentLayoutTemplateById(layoutId: string): Promise<any> {
    return super.get(api.document_layout_template_by_id + layoutId, {});
  }

  public async createDocumentLayoutTemplate(data: any): Promise<any> {
    const formData = new FormData();
    for (const [key, value] of Object.entries(data)) {
      formData.append(key, String(value));
    }
    return super.post(api.create_layout_templates, formData);
  }

  public async updateDocumentLayoutTemplateById(
    data: any,
    layoutId: string,
  ): Promise<any> {
    const formData = new FormData();
    for (const [key, value] of Object.entries(data)) {
      formData.append(key, String(value));
    }
    return super.put(api.document_layout_template_by_id + layoutId, formData);
  }

  public async deleteDocumentLayoutTemplate(templateId: any): Promise<any> {
    return super.delete(api.document_layout_template_by_id + templateId, {});
  }

  // Clone a layout template server-side. The backend copies the source
  // layout_json; we only pass the new title and the layout_type. org_id
  // rides in the X-ORG-ID header (injected by the base post()).
  public async cloneDocumentLayoutTemplate(
    layoutId: string,
    data: { title: string; layout_type: string },
  ): Promise<any> {
    const formData = new FormData();
    formData.append('title', data.title);
    formData.append('layout_type', data.layout_type);
    return super.post(
      api.document_layout_template_by_id + layoutId + '/clone',
      formData,
    );
  }

  public async applyDefaultLayoutToOrigins(data: any): Promise<any> {
    const formData = new FormData();
    for (const [key, value] of Object.entries(data)) {
      formData.append(key, String(value));
    }
    return super.post(api.apply_default_to_origins, formData);
  }

  public async getLayoutSelectionRules(queries: dynamicObj): Promise<any> {
    let querystring = '';
    if (Object.keys(queries).length !== 0) {
      querystring += '?';
      querystring += this.encodeQueryData(queries);
    }

    return super.get(api.layout_selection_rules + querystring, {});
  }

  public async toggleLayoutSelectionRule(
    ruleId: string,
    isActive: boolean,
  ): Promise<any> {
    // Body is exactly { is_active }; org_id travels in the X-ORG-ID header the
    // service injects, so skip appending it to the JSON payload.
    return super.patch(
      `${api.layout_selection_rules}/${ruleId}/toggle`,
      { is_active: isActive },
      { skipOrgId: true },
    );
  }

  public async createLayoutSelectionRule(payload: dynamicObj): Promise<any> {
    // JSON body; org_id is injected by the base post(). Everything else
    // (doc_type_key, layout_type, rule_key, applies_when, …) is on the payload.
    return super.post(api.layout_selection_rules, payload);
  }

  public async updateLayoutSelectionRule(
    ruleId: string,
    payload: dynamicObj,
  ): Promise<any> {
    // JSON body; org_id is injected by the base put().
    return super.put(`${api.layout_selection_rules}/${ruleId}`, payload);
  }

  public async cloneLayoutSelectionRule(
    ruleId: string,
    payload: { rule_key: string; display_name: string },
  ): Promise<any> {
    // The backend copies the source rule's whole definition (conditions, target
    // layout, priority); the body carries only the new row's identity. org_id
    // rides in the X-ORG-ID header, so keep it out of the JSON payload.
    return super.postWithoutOrgId(
      `${api.layout_selection_rules}/${ruleId}/clone`,
      { ...payload },
    );
  }

  public async deleteLayoutSelectionRule(ruleId: string): Promise<any> {
    return super.delete(`${api.layout_selection_rules}/${ruleId}`, {});
  }

  public async reorderLayoutSelectionRules(
    docTypeKey: string,
    layoutType: string,
    ruleKeys: string[],
  ): Promise<any> {
    // Body is exactly { doc_type_key, layout_type, rule_keys }; org_id rides in the
    // X-ORG-ID header, so use the no-body-org variant to keep the payload clean.
    return super.postWithoutOrgId(`${api.layout_selection_rules}/reorder`, {
      doc_type_key: docTypeKey,
      layout_type: layoutType,
      rule_keys: ruleKeys,
    });
  }

  public async setLayoutManagementPreferences(payload: dynamicObj): Promise<any> {
    const formData = new FormData();
    for (const [key, value] of Object.entries(payload)) {
      formData.append(key, String(value));
    }
    return super.post(api.layout_management_preferences, formData);
  }
}
