  public async refreshToken(data: tokenRequest): Promise<any> {
    // ⭐ CRITICAL FIX: Bypass AbstractApiService to prevent header override
    // AbstractApiService.post() overwrites Content-Type to 'application/json' for non-FormData payloads
    // This breaks URLSearchParams encoding required by OAuth2 RFC 6749
    //
    // Solution: Use axios client directly (inherited from ApiClient)
    // - OAuth2 endpoint doesn't need org_id (user-level auth, not org-specific)
    // - Ensures proper application/x-www-form-urlencoded encoding per RFC 6749

    const params = new URLSearchParams();
    params.append('grant_type', 'refresh_token');
    // ✅ RFC 6749 Compliance: Add client_id for public client authentication
    params.append('client_id', 'frontend');

    // Add refresh_token and other params
    for (const [key, value] of Object.entries(data)) {
      // Skip grant_type if it somehow exists in data - we always use 'refresh_token'
      if (key !== 'grant_type') {
        params.append(key, value);
      }
    }

    try {
      // Use axios client directly (inherited from ApiClient) instead of super.post()
      // This bypasses AbstractApiService's content-type override and org_id injection
      const response = await (this as any).client.post(api.get_token, params, {
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          // RFC 6749: Public client authentication uses client_id parameter only
          // Do NOT include Authorization header for public clients (token refresh also uses public client)
        },
      });
      return response.data;
    } catch (error: any) {
      // Re-throw the error response data for proper error handling
      throw error.response?.data || error;
    }
  }

