  // Feature subscription lifecycle endpoints

  public async createFeatureSubscription(
    data: FeatureSubscriptionCreateRequest,
  ): Promise<FeatureSubscription> {
    const formData = new FormData();
    formData.append('plan_id', data.plan_id);
    formData.append('start_date', data.start_date);
    if (data.end_date) {
      formData.append('end_date', data.end_date);
    }
    return super.post(api.feature_subscription_create, formData);
  }

