import AbstractApiService from '../abstractApiService';
import { api, DOC2API_URL } from 'pages/APIs';

export default class SystemLogsApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  public async getLogs(data: any): Promise<any> {
    return super.get(api.get_system_logs + '?' + data);
  }

  public async getLogStats(data: any): Promise<any> {
    return super.get(api.get_system_logs_count + '?' + data);
  }

  /**
   * Get per-level log counts for the stats cards (DOCB-12254).
   *
   * Calls doc2-api's org-scoped `/observability/logs/level_counts`
   * endpoint instead of issuing raw LogQL against the public Loki read
   * ingress. Org + environment scoping is server-derived from the auth
   * token; the fixed 168h (7d) window preserves the old hardcoded `[7d]`
   * LogQL range.
   *
   * @param service friendly service name from the page's dropdown
   *                (e.g. `doc2-api`), or undefined for all services
   * @param search  optional free-text search term filter
   * @returns `{ total, errors, warnings, info, debug }` (all ints)
   */
  public async getLogCounts(service?: string, search?: string): Promise<any> {
    const params = new URLSearchParams();
    params.append('hours', '168');
    if (service) {
      params.append('service', service);
    }
    if (search) {
      params.append('search', search);
    }

    const url = `${DOC2API_URL}/observability/logs/level_counts?${params.toString()}`;

    try {
      return await this.getWithoutOrgId(url);
    } catch (error) {
      console.error('[SystemLogsApiService] Error in getLogCounts:', error);
      throw error;
    }
  }

  public async getLogDetail(logId: string): Promise<any> {
    const params = new URLSearchParams();
    params.append('search', logId);
    params.append('page_size', '1');

    return super.get(api.get_system_logs + '?' + params.toString());
  }

  public async exportLogs(data: any): Promise<any> {
    return super.get(api.get_system_logs + '?' + data);
  }

  public async getErrorSummary(): Promise<any[]> {
    return super.get(api.get_system_logs_summary);
  }

  public async getSystemHealth(): Promise<any> {
    return super.get(api.get_system_health);
  }

  public async getComponentHealth(componentName: string): Promise<any> {
    return super.get(
      api.get_system_component_health.replace(':component_name', componentName),
    );
  }

  public async getSystemInfo(): Promise<any> {
    return super.get(api.get_system_info);
  }

  public async getSystemMetrics(): Promise<any> {
    return super.get(api.get_system_metrics);
  }

  public async getAvailableServices(): Promise<{ [key: string]: string }> {
    return Promise.resolve({
      'doc2-api': 'doc2-api',
      'extraction-service': 'extraction-service',
      'ocr-service': 'ocr-service',
      'workflow-service': 'workflow-service',
      'auto-accounting': 'auto-accounting',
      'import-email': 'import-email',
      'import-ftp': 'import-ftp',
      docflow: 'docflow',
      operator: 'operator',
      docnet: 'docnet',
    });
  }
}
