export interface ResolvedLayoutSource {
  matched_by: string;
  rule_key: string;
  watched_fields: string[];
}

export interface ResolvedLayout {
  payload: Record<string, any>;
  templateId: string;
  hash: string;
  source: ResolvedLayoutSource;
}

/**
 * What the store remembers about a rule-resolved layout. The question that
 * produced it (`doc_id`, `layout_type`) is part of the stamp so a re-resolve
 * can ask it again — screens do not have to hold on to it themselves.
 * An empty `hash` means the loaded layout did not come from a rule.
 */
export interface ResolvedLayoutStamp {
  hash: string;
  doc_id: string;
  layout_type: string;
  source: ResolvedLayoutSource;
}

export function emptyResolvedLayoutStamp(): ResolvedLayoutStamp {
  return {
    hash: '',
    doc_id: '',
    layout_type: '',
    source: { matched_by: '', rule_key: '', watched_fields: [] },
  };
}

const HEADER_PREFIX = 'header.';

/**
 * Shape of `GET /document_layout_template/resolve`:
 *   { layout: { id, layout_json }, layout_hash, matched_by, rule_key, watched_fields }
 *
 * Returns null when the response carries no usable layout — routine when no
 * rule matched, a backend defect when `layout_json` is there but unusable.
 * Callers tell the two apart by looking at `data.layout?.layout_json`.
 */
export function parseResolvedLayout(data: any): ResolvedLayout | null {
  const template = data?.layout;
  const raw = template?.layout_json;
  if (typeof raw !== 'string' || !raw) {
    return null;
  }

  let payload: any;
  try {
    payload = JSON.parse(raw);
  } catch {
    return null;
  }

  if (!payload || !Array.isArray(payload.layout)) {
    return null;
  }

  return {
    payload,
    templateId: String(template.id ?? ''),
    hash: data.layout_hash ? String(data.layout_hash) : '',
    source: {
      matched_by: String(data.matched_by ?? ''),
      rule_key: String(data.rule_key ?? ''),
      watched_fields: Array.isArray(data.watched_fields)
        ? data.watched_fields.map(String)
        : [],
    },
  };
}

/**
 * Could a save have moved this document to another layout?
 *
 * Only `header.*` entries are editable on the validation and approval screens,
 * so `doc.*` ones can never be the reason. `changed = null` means the change
 * set could not be determined — that is not "nothing changed", so any watched
 * header field is then reason enough to re-resolve.
 */
export function watchedFieldsMayHaveChanged(
  watched: string[],
  changed: Set<string> | null,
): boolean {
  return watched
    .map((entry) => String(entry ?? '').trim())
    .filter((entry) => entry.startsWith(HEADER_PREFIX))
    .map((entry) => entry.slice(HEADER_PREFIX.length))
    .some((field) => !changed || changed.has(field));
}
