import { LocalStorage, SessionStorage } from 'quasar';
import { clearAllObjectsFromIndex } from 'src/utils/indexedDb';
import { useAuthTokenStore } from 'src/store/main';
import { documentLockApiService } from 'src/services';
import { setApiRegion, clearPersistedApiRegion } from 'src/pages/api-base-url';
import { clearServiceWorkerCaches } from 'src/utils/cacheRecovery';
import { AUTH_URL } from 'src/pages/APIs';
import { clearFaroUser } from 'src/boot/faro';

// OAuth2 revocation endpoint (RFC 7009). Hardcoded path so that a broken
// SDK or import does not block logout — if anything in the stack here
// throws, the user must still be logged out.
const REVOKE_TOKEN_PATH = '/v2/oauth2/revoke';

// Auth-service logout endpoint. Blacklists the current access_token
// (Redis-backed) and clears the user's server-side cache. Distinct from
// revoke, which kills the refresh_token — together they fully invalidate
// the session server-side.
const LOGOUT_PATH = '/v2/auth/logout';

// Upper bound we wait for the blacklist call before redirecting: long enough
// to be observable (synthetic monitors assert the 2xx) and to actually land,
// short enough that a slow or hanging auth-service never traps the user on a
// half-torn-down page.
const LOGOUT_BLACKLIST_TIMEOUT_MS = 2000;

const TAB_CHANNEL_NAME = 'docbits-tab-channel';
export const tabChannel: BroadcastChannel | null =
    typeof BroadcastChannel !== 'undefined'
        ? new BroadcastChannel(TAB_CHANNEL_NAME)
        : null;

// On `window` (not module scope) so duplicate module copies in the same tab
// share the flag — handleCrossTabMessage uses it to drop self-sent LOGOUT.
declare global {
    interface Window {
        __docbits_logging_out?: boolean;
    }
}

/**
 * Invalidate this session's refresh_token server-side, so a stolen one can't be
 * used after the user logs out.
 *
 * Best-effort by design: never awaited (a slow /oauth2/revoke must not delay
 * logout), `keepalive` lets the POST outlive the redirect, and all errors are
 * swallowed. Worst case the refresh_token lives to its natural 30-day expiry.
 */
function revokeRefreshTokenBestEffort(): void {
    try {
        const tokenDetails = LocalStorage.getItem('token_details') as {
            refresh_token?: string;
        } | null;
        const refreshToken = tokenDetails?.refresh_token;
        if (!refreshToken) {
            return;
        }
        const body = new URLSearchParams({
            token: refreshToken,
            token_type_hint: 'refresh_token',
        });
        void fetch(AUTH_URL + REVOKE_TOKEN_PATH, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
            },
            body: body.toString(),
            keepalive: true,
            credentials: 'omit',
        }).catch(() => {
            // Swallow: best-effort revoke. Server may be slow or down;
            // refresh_token will then simply rely on its natural expiry.
        });
    } catch {
        // Storage corruption, type mismatch, etc. must never block logout.
    }
}

/**
 * Blacklist the current access_token so it cannot be replayed after logout.
 *
 * Unlike revoke this is *awaited*, so the token is really dead before we hand
 * back control (and synthetic monitors can observe the 2xx) — but capped at
 * LOGOUT_BLACKLIST_TIMEOUT_MS so a hanging auth-service can't trap the user
 * mid-logout. Errors are swallowed; logout proceeds regardless.
 */
async function blacklistAccessToken(): Promise<void> {
    let accessToken: string | undefined;
    try {
        const tokenDetails = LocalStorage.getItem('token_details') as {
            access_token?: string;
        } | null;
        accessToken = tokenDetails?.access_token;
    } catch {
        // Storage corruption etc. must never block logout.
        return;
    }
    if (!accessToken) {
        return;
    }
    const controller = new AbortController();
    const timer = setTimeout(
        () => controller.abort(),
        LOGOUT_BLACKLIST_TIMEOUT_MS,
    );
    try {
        await fetch(AUTH_URL + LOGOUT_PATH, {
            method: 'POST',
            headers: {
                Authorization: `Bearer ${accessToken}`,
            },
            signal: controller.signal,
            credentials: 'omit',
        });
    } catch {
        // Network error / timeout / abort: best-effort, logout proceeds.
    } finally {
        clearTimeout(timer);
    }
}

// Keys to preserve on logout (user preferences & app state)
// Keep these as literals instead of reading CONSTANTS at module load time.
// LogoutUtil is pulled into early auth/cache chunks; top-level CONSTANTS access
// can create a production bundle cycle and prevent Vue from mounting.
const KEEP_ON_LOGOUT = new Set([
    'selected_language',
    'remembered_email',
    'auth_region',
    'APP_VERSION',
    'versionRefreshCooldownUntil',
    'tasks_list_mode',
    'fullSearchFilters',
    'group_parent_indexes',
    'group_parent_raw_where',
    'IMPORT_LOG_SETTING_COLUMNS',
    'EXPORT_SETTING_COLUMNS_ORDER',
    'USERS_SETTING_COLUMNS_ORDER',
    'GROUPS_COLUMNS_ORDER',
    'GROUPS_SORT_ORDER',
    'SUB_ORG_COLUMNS_ORDER',
    'EMAIL_TEMPLATE_SETTING_COLUMNS_ORDER',
    'EMAIL_NOTIFICATION_SETTING_COLUMNS_ORDER',
    'SUPPLIER_EMAIL_TEMPLATE_SETTING_COLUMNS_ORDER',
    'CUSTOM_COLUMNS_ORDER',
    'CLASSIFICATION_EXTRACTION_SETTING_COLUMNS',
    'TASKS_COLUMNS_SETTING',
    'TASKS_LIST_SETTINGS',
    'workflow_dashboard_filters',
]);

// Substrings of dynamic user-based keys to preserve (e.g. {userId}_dashboard_filters_v2)
const KEEP_PATTERNS_ON_LOGOUT = [
    'dashboard_filters_v2',
    'dashboard_groups',
    'dashboard_pagination',
    'columnWidths_',
    'columnFilter_',
    'columnResize',
    'orderBy_',
    'Log-Settings',
    'emailImport',
    'ftpImport',
    'listOfValues',
    'script_logs_setting',
    'masterDataTabs',
    'lov_custom_order_',
];

function shouldKeepOnLogout(key: string): boolean {
    if (KEEP_ON_LOGOUT.has(key)) return true;
    return KEEP_PATTERNS_ON_LOGOUT.some((pattern) => key.includes(pattern));
}

// Expire every cookie document.cookie exposes. A delete only lands when the
// expiry matches the cookie's exact path+domain, so each one is re-issued across
// every combination it could have been set with: path '/' plus each cumulative
// prefix of the current pathname, and domain unset / host / dot-host.
//
// Only reaches non-HttpOnly, root-path cookies (analytics, feature flags) — a
// document.cookie limit, not a gap: the real session cookie is HttpOnly on the
// auth-service domain and is killed by the revoke + blacklist calls, not here.
function clearBrowserCookies() {
    if (typeof document === 'undefined' || !document.cookie) {
        return;
    }
    const expiry = 'expires=Thu, 01 Jan 1970 00:00:00 GMT';
    const host = window.location.hostname;

    // Cumulative path prefixes of the current pathname, root first.
    const paths = ['/'];
    let acc = '';
    for (const segment of window.location.pathname.split('/').filter(Boolean)) {
        acc += '/' + segment;
        paths.push(acc);
    }

    document.cookie.split(';').forEach((cookie) => {
        const name = cookie.split('=')[0].trim();
        if (!name) return;
        for (const path of paths) {
            document.cookie = `${name}=;${expiry};path=${path}`;
            document.cookie = `${name}=;${expiry};path=${path};domain=${host}`;
            document.cookie = `${name}=;${expiry};path=${path};domain=.${host}`;
        }
    });
}

function clearStorageForLogout() {
    const auth_token_store = useAuthTokenStore();
    auth_token_store.$reset();

    // Clear all localStorage keys except the ones we want to keep
    const keysToRemove: string[] = [];
    for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && !shouldKeepOnLogout(key)) {
            keysToRemove.push(key);
        }
    }
    keysToRemove.forEach((key) => LocalStorage.remove(key));

    clearAllObjectsFromIndex();
    SessionStorage.clear();
    clearBrowserCookies();
    setApiRegion('eu');
    clearPersistedApiRegion();

    // Detach org/user context from RUM telemetry (DOCB-12254). Mostly
    // defensive — logout navigates to '/' which re-inits Faro anyway —
    // but covers telemetry sent between storage wipe and navigation.
    clearFaroUser();
}

function unlockDoc(doc_id: any, doc_lock: any) {
    const params = {
        doc_id: doc_id,
        lock_key: doc_lock,
        force: 'true',
    };
    documentLockApiService.release(params);
}

async function logout() {
    // Defensive calls without a token (e.g. redirectToLogin during boot on /)
    // must not navigate — would cascade-reload sibling tabs.
    const hadSession = !!LocalStorage.getItem('token_details');

    const cached_doc_id = SessionStorage.getItem('doc_cached_id') as string;
    const lock_key = SessionStorage.getItem('doc_lock_key') as string;
    if (cached_doc_id && lock_key) {
        unlockDoc(cached_doc_id, lock_key);
    }

    if (hadSession) {
        // Set BEFORE postMessage so a same-tab duplicate channel sees it.
        window.__docbits_logging_out = true;
        // Invalidate server-side BEFORE clearing storage — tokens needed.
        // revoke kills refresh_token (fire-and-forget); blacklist kills
        // access_token (awaited so it actually lands).
        revokeRefreshTokenBestEffort();
        await blacklistAccessToken();
    }

    // Always wipe storage — guarantees no leaked Pinia/IndexedDB/Session state.
    //
    // Removing `token_details` is ALSO what logs out every other tab (it fires a
    // native 'storage' event — see src/boot/main.js). Signalling *by* clearing
    // the token, rather than sending a separate "please log out" message before
    // the wipe, is what closes the window where a sibling could reload, still
    // find a valid token, and be sent straight back to /dashboard.
    clearStorageForLogout();

    if (hadSession) {
        // DOCB-13889: broadcast AFTER the storage wipe. Siblings hard-reload
        // to '/' on receipt; broadcasting first gave them up to ~2s (the
        // blacklist await) to reload while the dead token_details was still
        // in localStorage — the '/' route's isTokenExpired() check then
        // bounced them straight back into /dashboard on a server-revoked
        // token, whose forced refresh failed with invalid_grant and toasted
        // "Authentifizierungsfehler" + "Sitzungsaktualisierung fehlgeschlagen".
        if (tabChannel) {
            try {
                tabChannel.postMessage({ type: 'LOGOUT' });
            } catch (err) {
                console.error('[LogoutUtil] failed to broadcast LOGOUT:', err);
            }
        }
        // Drop the service-worker cache so the next session never gets a stale
        // cached response. Awaited so deletion lands before the navigation
        // cancels it. Gated on hadSession: a defensive boot-time logout
        // (redirectToLogin on `/`) must NOT nuke the precache on every load.
        await clearServiceWorkerCaches();
        window.location.href = '/';
    }
}

export {
    logout,
    clearStorageForLogout,
    shouldKeepOnLogout,
    revokeRefreshTokenBestEffort,
    blacklistAccessToken,
    KEEP_ON_LOGOUT,
    KEEP_PATTERNS_ON_LOGOUT,
    REVOKE_TOKEN_PATH,
    LOGOUT_PATH,
};
