/* eslint-disable @typescript-eslint/no-unsafe-return */
import { i18n } from 'src/boot/i18n';
import stringUtil from 'src/utils/string';
import { isUndefinedOrNull } from 'src/utils/general';


export default {
  mixins: [stringUtil],
  methods: {
    displayFieldLabel(row, prefix = '', show_translation_key = true) {

      let label = '';
      try {
        if (isUndefinedOrNull(row)) {
          return label;
        }

        const field_key = row.field_name || row.document_name || row.document_key;
        const translation_key = prefix + (row.translation_key || field_key);
        const translation = this.translateLabel(translation_key);
        // translateLabel echoes the key back when nothing matched.
        const has_translation = translation !== translation_key;

        label = row.title || '';

        // A bundled translation always wins: it is the only label that follows
        // the user's locale. A custom field_label is a single static string, so
        // it may only fill the gap where no translation exists — otherwise one
        // admin's rename would pin one language for every user.
        if (has_translation) {
          label = translation;
        } else if (row.field_label) {
          label = row.field_label;
        }

        if (!label && show_translation_key) {
          label = field_key;
        }
      } catch (err) {
        logError(err);
      }
      return label;
    },
    translateLabel(translation_key) {
      let translation = '';
      try {
        if (!translation_key) {
          return translation;
        }

        // Try the full key
        translation = i18n.t(translation_key);
        if (translation != translation_key) {
          return translation;
        }

        // Try lowercase
        const lower_key = translation_key.toLowerCase();
        const lower_translation = i18n.t(lower_key);
        if (lower_translation != lower_key) {
          return lower_translation;
        }

        // Nothing matched — hand back the key so callers can detect the miss.
        return translation_key;
      } catch (err) {
        logError(err);
      }
      return translation;
    },
    getFieldLabel(row, prefix = '', show_translation_key = false) {
      if (isUndefinedOrNull(row)) {
        return '';
      }

      let label = this.displayFieldLabel(row, prefix, show_translation_key);
      return label ? label : String(row.label ? row.label : '');
    },

    getFieldLabelWithFallbacks(row) {
      const label =
        this.displayFieldLabel(row) || this.getFieldLabel(row, '', true);
      return label ? label : String(row.label);
    },
    getLabelToDisplay(item) {
      let translation_key = item.translation_key;

      if (!translation_key) {
        translation_key = item.column_name ? item.column_name : item.name;
      }

      let label = this.translateLabel(translation_key);

      if (!label || label == translation_key) {
        label = item.title;
      }

      return label;
    },
    keyFormatter(key) {
      // remove _ from key
      if (!key) {
        return '';
      }
      return key.replace(/_/g, ' ');
    },
    formatTextAndTranslate(str, strToSearch, replacement) {
      if (!str) {
        return '';
      }
      let label = str.toLowerCase();
      if (strToSearch && replacement) {
        label = this.stringReplaceWithString(label, strToSearch, replacement);
      }

      const translated_label = this.translateLabel(label);

      // translateLabel echoes the key back when nothing matched.
      return translated_label == label ? this.formatText(label) : translated_label;
    },
  },
};
