/**
 * Shared Token Management Helpers
 *
 * Centralized auth-token helpers used by BOTH axios mutators:
 * - auth-axios-instance.ts (auth service requests)
 * - custom-axios-instance.ts (regular SDK requests)
 *
 * Previously these three functions were duplicated in each mutator, which drifted
 * out of sync and hid a bug (a logout call guarded on a store method that never
 * existed). Keeping them here means one implementation, one place to fix.
 *
 * All functions use lazy dynamic imports to avoid circular dependencies with the
 * auth store / cache utilities during boot.
 */

/**
 * Get current access token from auth store.
 *
 * The auth store exposes async getAuthorizationToken(), which validates and
 * refreshes tokens. It returns a "Bearer <token>" string; this strips the
 * "Bearer " prefix and returns the raw token so callers don't double-prefix
 * when they set the Authorization header.
 */
export async function getAuthToken(): Promise<string | null> {
  try {
    const { useAuthTokenStore } = await import('src/store/User/auth_token.store');
    const authStore = useAuthTokenStore();

    const authHeader = await authStore.getAuthorizationToken();
    if (!authHeader) {
      return null;
    }

    const token = authHeader.replace(/^Bearer\s+/i, '');
    return token || null;
  } catch (error) {
    console.warn('Warning: Could not retrieve auth token:', error);
    return null;
  }
}

/**
 * Refresh access token using the auth store's refresh logic.
 *
 * Like getAuthToken(), this strips the "Bearer " prefix from the returned
 * authorization header to prevent a double "Bearer " in requests.
 *
 * @param failingToken The raw access token the 401'd request was sent with
 *   (DRFS-664). Lets the store distinguish "another tab already rotated the
 *   token" (skip) from "the stored token was just rejected" (must refresh).
 */
export async function refreshAccessToken(
  failingToken?: string,
): Promise<string | null> {
  try {
    const { useAuthTokenStore } = await import('src/store/User/auth_token.store');
    const authStore = useAuthTokenStore();

    const refreshed = await authStore.refreshToken(failingToken);
    if (!refreshed) {
      return null;
    }

    const authHeader = await authStore.getAuthorizationToken();
    if (!authHeader) {
      return null;
    }

    const token = authHeader.replace(/^Bearer\s+/i, '');
    return token || null;
  } catch (error) {
    console.error('Token refresh failed:', error);
    return null;
  }
}

/**
 * Handle token refresh failure by triggering the canonical app logout.
 *
 * Delegates to cache.methods.logout() — the same logout path the auth store
 * itself uses — which clears auth state, broadcasts to sibling tabs, and
 * redirects to login.
 */
export async function handleTokenRefreshFailure(): Promise<void> {
  try {
    const { default: cache } = await import('src/utils/cache');
    await cache.methods.logout();
  } catch (error) {
    console.error('Error during logout:', error);
  }
}
