import { date } from 'quasar';
import { defineStore } from 'pinia';
import dateUtils from 'src/utils/date';
import { Acl } from 'src/core/acls/index';
import { userApiService } from 'src/services';
import { taskApiService } from 'src/services';
import { useSettingStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import { LocalStorage, SessionStorage } from 'quasar';
import { replacer, reviver } from 'src/utils/mapUtil';
import { tasks_notification_setting, CONSTANTS } from 'src/constants';
import { getUserDetailFromkey, isUserAdmin } from 'src/utils/UserDetails';
import { isUndefinedOrNull, toPositiveInt, idsEqual } from 'src/utils/general';

// How many records a Kanban column reveals, and requests, at a time.
export const BOARD_PAGE_SIZE = 10;

export interface ColumnWithExtras {
  title: string;
  tasks: any[];
  visibleCount: number;
  loadingMoreTasks: boolean;
  // Set once the server has no further records for this column's status,
  // so scrolling stops asking for pages that will always come back empty.
  all_loaded: boolean;
}

const makeColumn = (title: string): ColumnWithExtras => ({
  title,
  tasks: [],
  visibleCount: BOARD_PAGE_SIZE,
  loadingMoreTasks: false,
  all_loaded: false,
});

export const useTaskStore = defineStore('tasks_store', {
  state: () => ({
    tasks: [] as dynamicObj[],
    document_related_tasks: [] as dynamicObj[],
    tasks_loading: false,
    total_document_tasks: 0,
    total_records: 0,
    open_task_count: 0,
    offset: 0,
    page_size: 10,
    processing: false,
    sort_by: 'created_on',
    sort_order: 'desc',
    data_fetched: false,
    status: '',
    taskListSettingsMap: new Map(),
    taskfiltersMap: new Map(),
    tasks_list_settings_key: CONSTANTS.tasks_list_settings,
    columnKey: CONSTANTS.tasks_columns,
    list_mode: false,
    columns: ['open', 'in_progress', 'done', 'rejected'].map(makeColumn),

    // Filters/sort the board columns were paged with — column offsets are only
    // valid while this stays the same.
    board_filter_signature: '',
    // Bumped every time the columns are re-split, so the board can top them up
    // afterwards instead of guessing when the split happened.
    board_revision: 0,

    task: {} as dynamicObj,
    timeOptions: [] as dynamicObj[],
    task_date_format: 'YYYY/MM/DD',
    selectionList: [] as any,
    is_module_on: false,
    statusList: [] as any,
    headerCheckbox: false,
    total_pages: 0,
    current_page: 1,
    show_table_loader: false,
    userGroupIds: [] as any,
    isUserAdmin: isUserAdmin(),
    userId: getUserDetailFromkey('id'),
    list_size_key: 'TASK_PAGINATION_SIZE',
  }),
  getters: {},
  actions: {
    resetColumns(reset_paging = true) {
      this.columns.forEach((column: ColumnWithExtras) => {
        column.tasks = [];
        column.loadingMoreTasks = false;
        if (reset_paging) {
          column.visibleCount = BOARD_PAGE_SIZE;
          column.all_loaded = false;
        }
      });
    },

    formatTaskList() {
      const signature = JSON.stringify([
        this.getSavedFiltersAsJson(),
        this.sort_by,
        this.sort_order,
      ]);
      const filters_changed = signature !== this.board_filter_signature;
      this.board_filter_signature = signature;

      // Records pulled in by column scrolling live past the shared page in
      // `tasks`. A background refresh must not throw them away, or the board
      // jumps back to the first page every minute. Changed filters invalidate
      // them, since the column offsets no longer mean anything.
      const page_ids = new Set(this.tasks.map((task: any) => String(task.id)));
      const paged_tasks = filters_changed
        ? []
        : this.columns.flatMap((column: ColumnWithExtras) =>
            column.tasks.filter((task: any) => !page_ids.has(String(task.id))),
          );

      this.resetColumns(filters_changed);
      [...this.tasks, ...paged_tasks].forEach((task: any) => {
        const column = this.columns.find(
          (item: ColumnWithExtras) => item.title === task.status,
        );
        if (column) {
          this.addTaskToColumn(column, task);
        }
      });
      this.board_revision++;
    },

    addTaskToColumn(column: ColumnWithExtras, task: any) {
      const exists = column.tasks.some(
        (item: any) => String(item.id) === String(task.id),
      );
      if (exists) {
        return false;
      }
      column.tasks.push(task);
      return true;
    },

    // A column shows exactly one status, so paging it means a status-scoped
    // request starting after the records that column already holds.
    boardColumnParams(column: ColumnWithExtras) {
      const params = this.getSavedFiltersAsJson();
      params['status'] = column.title;
      params['document_fields'] = 'supplier_name,supplier_id';
      params['cache'] = false;
      params['skip'] = toPositiveInt(column.tasks.length, 0);
      params['limit'] = BOARD_PAGE_SIZE;
      params['sort_by'] = this.sort_by;
      params['order'] = this.sort_order;
      return params;
    },

    // Read from the normalised request params rather than the raw filter map,
    // so every shape the status filter can take ends up as a status list.
    statusIsVisibleInBoard(status: string) {
      const filter = this.getSavedFiltersAsJson()['status'];
      if (isUndefinedOrNull(filter) || filter === '') {
        return true;
      }
      return String(filter).split(',').includes(status);
    },

    /**
     * Shows more of a column: first the records it already holds, then the next
     * page of its status from the server. Resolves to true when something new
     * became visible.
     */
    async showMoreColumnTasks(column: ColumnWithExtras) {
      if (column.loadingMoreTasks) {
        return false;
      }
      if (column.visibleCount < column.tasks.length) {
        column.visibleCount = Math.min(
          column.visibleCount + BOARD_PAGE_SIZE,
          column.tasks.length,
        );
        return true;
      }
      if (column.all_loaded) {
        return false;
      }
      // The status filter hides this queue entirely — never page it.
      if (!this.statusIsVisibleInBoard(column.title)) {
        column.all_loaded = true;
        return false;
      }

      column.loadingMoreTasks = true;
      try {
        const response = await taskApiService.getTasks(
          this.boardColumnParams(column),
        );
        if (response.success === false) {
          throw response;
        }

        const records = this.extractTaskRecords(response);
        let added = 0;
        records.forEach((record: dynamicObj) => {
          this.applyBoardTaskFormat(record);
          if (this.addTaskToColumn(column, record)) {
            // Keep the shared list in sync so selection, bulk status updates
            // and the list view also see cards that arrived by paging.
            this.tasks.push(record);
            column.visibleCount++;
            added++;
          }
        });

        column.all_loaded = records.length < BOARD_PAGE_SIZE;
        // `added` rather than `records.length`: an all-duplicates page means the
        // offset cannot advance, so callers must stop instead of asking again.
        return added > 0;
      } catch (error) {
        logError(`Error loading more tasks for column ${column.title}`, error);
        return false;
      } finally {
        column.loadingMoreTasks = false;
      }
    },

    // Same normalisation TaskPage applies to the shared page, so a record does
    // not look different above and below the paging boundary.
    applyBoardTaskFormat(record: dynamicObj) {
      record['fabAction'] = false;
      record['rowSelection'] = false;
      if (record['deadline']) {
        const { formatted_deadline } = this.getDisplayDeadline(
          record['deadline'],
        );
        record['deadline'] = formatted_deadline;
      }
    },
    async saveTaskColumns(columns: dynamicObj) {
      try {
        const settings_store = useSettingStore();
        const result = await settings_store.updateSetting(
          this.columnKey.toUpperCase(),
          JSON.stringify(columns),
        );
        LocalStorage.set(this.columnKey, JSON.stringify(columns));
        settings_store.user_settings[this.columnKey.toUpperCase()] =
          JSON.stringify(columns);
        return result;
      } catch (error) {
        logError('Error saving task columns', error);
      }
    },
    resetTaskStore() {
      this.task = {};
    },

    async getTask(id: string, use_cache = true) {
      try {
        this.processing = true;

        this.task = {};
        const response = await taskApiService.getTaskById(id, use_cache);

        if (response.success === false) {
          throw response;
        }
        this.task = response.data;
        this.afterTaskGet();
      } catch (error) {
        throw error;
      } finally {
        this.processing = false;
      }
    },

    afterTaskGet() {
      if (
        !isUndefinedOrNull(this.task.assigned_to_user_id) &&
        this.task.assigned_to_user_id != 0
      ) {
        this.task['assigned_to_group'] = false;
      } else {
        this.task['assigned_to_group'] = true;
      }
    },

    // will be used from ACL store
    async loadUserAcls() {
      try {
        const response = await userApiService.getUserAcls();
        this.userGroupIds = response.group_permissions.map(
          (group: { group_id: string }) => group.group_id,
        );
      } catch (error) {
        return error;
      }
    },

    prepareOpenTaskParams(document_id: any = '') {
      const params: dynamicObj = {};
      if (document_id && document_id != '') {
        params['document_id'] = document_id;
      }
      params['status'] = 'open,in_progress';
      return params;
    },

    async getOpenTasks(document_id: any = '') {
      const params = this.prepareOpenTaskParams(document_id);
      await this.getTasks(params);
    },

    makeDefaultParams(params: dynamicObj) {
      const skip =
        params.document_id && params.document_id != '' ? 0 : this.offset; // Don't skip if document_id is present
      const limit = params.hasOwnProperty('limit')
        ? params.limit
        : this.page_size;
      const default_params = {
        // Guard against NaN/undefined reaching the API (-> HTTP 422). DOCB-12859.
        // offset 0 is valid (first page); NaN/negative collapse to 0.
        skip: toPositiveInt(skip, 0),
        limit: toPositiveInt(limit, 10),
        sort_by: this.sort_by,
        order: this.sort_order,
      };

      return default_params;
    },

    resetBeforeRequest(params: dynamicObj) {
      this.tasks_loading = true;
      this.data_fetched = false;
      if (params.hasOwnProperty('document_id')) {
        this.total_document_tasks = 0;
      } else {
        this.total_records = 0;
      }
    },

    async getTasks(params: dynamicObj) {
      const default_params = this.makeDefaultParams(params);
      Object.assign(params, default_params);
      // delete key document_id from params
      // delete params.document_id;

      const response = await taskApiService.getTasks(params);
      if (response.success === false) {
        throw response;
      }
      this.updateTaskData(response, params);
    },

    extractTaskRecords(response: dynamicObj) {
      const tasks = [] as dynamicObj[];
      const responseData =
        response?.data && typeof response.data === 'object'
          ? response.data
          : {};
      for (const [, item] of Object.entries(responseData)) {
        const record = item as dynamicObj;
        record.done_task_icon = 'radio_button_unchecked';
        record.rowSelection = false;
        record.created_on = dateUtils.methods.formatDateAccordingToPreference(
          record.created_on,
        );
        tasks.push(record);
      }
      return tasks;
    },

    updateTaskData(response: dynamicObj, params: dynamicObj) {
      this.resetBeforeRequest(params);
      const tasks = this.extractTaskRecords(response);
      const metadata =
        response?.metadata && typeof response.metadata === 'object'
          ? response.metadata
          : {};
      if (metadata.hasOwnProperty('total_results')) {
        if (params.hasOwnProperty('document_id')) {
          this.document_related_tasks = tasks;
          this.total_document_tasks = metadata.total_results;
        } else {
          this.tasks = tasks;
          this.total_records = metadata.total_results;
        }
      }

      this.tasks_loading = false;
      this.data_fetched = true;
    },

    // date Time Utility Functions
    // Deadlines are stored as UTC by the backend. Parse UTC-aware (a naive
    // timestamp is anchored to UTC, an offset-bearing one is honoured) via the
    // shared converter in src/utils/date.ts, then render with LOCAL getters so
    // every viewer sees the SAME instant in their own zone. The previous
    // implementation shifted the naive timestamp by the *viewer's* offset
    // (creator and approver saw different wall-clock times) and turned an
    // offset-bearing input into "12:NaN AM" (DTLG-54).
    getDisplayDeadline(deadline: string) {
      const dateObj = dateUtils.methods.toUtcAwareDate(deadline);
      if (!dateObj) {
        return {
          formated_date: deadline,
          formatted_time: '',
          formatted_deadline: deadline,
        };
      }

      const formated_date = date.formatDate(dateObj, this.task_date_format);
      const formatted_time = this.getDeadlineTime(dateObj);
      const formatted_deadline = this.makeDeadline(
        formatted_time,
        formated_date,
      );

      return {
        formated_date,
        formatted_time,
        formatted_deadline,
      };
    },

    makeTimeOptions() {
      this.timeOptions = [];
      for (let hour = 0; hour <= 23; hour++) {
        for (let minute = 0; minute < 60; minute += 15) {
          const time = this.formatTime(hour, minute);
          this.timeOptions.push({
            label: time,
            value: time,
          });
        }
      }
    },

    formatTime(hour: number, minute: number) {
      const ampm = hour >= 12 ? 'PM' : 'AM';
      hour = hour % 12;
      hour = hour ? hour : 12; // Handle midnight (0:00)
      const new_minute = minute < 10 ? '0' + minute : minute;
      return hour + ':' + new_minute + ' ' + ampm;
    },

    getDeadlineTime(date = null as Date | null) {
      let newTime = new Date();

      if (isUndefinedOrNull(date)) {
        newTime = new Date(new Date().getTime() + 30 * 60000); // 30 minutes in milliseconds
        const roundedMinutes = Math.round(newTime.getMinutes() / 15) * 15;
        newTime.setMinutes(roundedMinutes);
      } else {
        newTime = new Date(date!.getTime());
      }

      let hours = newTime.getHours();
      const minutes = newTime.getMinutes();
      const ampm = hours >= 12 ? 'PM' : 'AM';
      hours = hours % 12;
      hours = hours ? hours : 12; // Handle midnight (0:00)
      const new_minutes = minutes < 10 ? '0' + minutes : minutes;
      return hours + ':' + new_minutes + ' ' + ampm;
    },

    getIsoFormatDate(date_to = null as Date | null) {
      if (isUndefinedOrNull(date_to) || date_to!.toString() == 'Invalid Date') {
        date_to = new Date();
      }

      let date_iso_format = '';
      if (date_to != null) {
        date_iso_format = date.formatDate(date_to, 'YYYY-MM-DDTHH:mm:ss.SSSZ');
      }

      return date_iso_format;
    },

    makeDeadline(time: any, date: any) {
      if (time && date) {
        return date + ' ' + time;
      }
    },
    //END date Time Utility Functions

    // Search Utility Functions

    getSavedListSettings() {
      try {
        const value = LocalStorage.getItem(
          this.tasks_list_settings_key,
        ) as string;
        const newValue = JSON.parse(value, reviver);
        if (newValue) {
          this.taskListSettingsMap = newValue;
          this.parseSettings();
        }

        if (isUndefinedOrNull(newValue)) {
          this.setDefaultSettings();
        }
      } catch (err) {}
    },

    parseSettings() {
      if (this.taskListSettingsMap.size == 0) {
        this.setDefaultSettings();
      }

      if (this.taskListSettingsMap.has('filters')) {
        this.taskfiltersMap = this.taskListSettingsMap.get('filters');
      }

      /*if (this.taskListSettingsMap.has('page_size')) {
        this.page_size = this.taskListSettingsMap.get('page_size');
      }*/

      if (this.taskListSettingsMap.has('sort_by')) {
        const savedSortBy = this.taskListSettingsMap.get('sort_by');
        if (savedSortBy) {
          this.sort_by = savedSortBy;
        }
      }

      if (this.taskListSettingsMap.has('sort_order')) {
        const savedSortOrder = this.taskListSettingsMap.get('sort_order');
        if (savedSortOrder) {
          this.sort_order = savedSortOrder;
        }
      }
    },

    resetFilters() {
      this.setDefaultSettings();
      this.saveListSettings();
    },

    deleteItemInFiltersMap(key: string) {
      if (this.taskfiltersMap.has(key)) {
        this.taskfiltersMap.delete(key);
      }

      this.setListSettings('filters', this.taskfiltersMap);
    },

    setItemInFiltersMap(key: string, value: any) {
      this.taskfiltersMap.set(key, value);
      this.setListSettings('filters', this.taskfiltersMap);
    },

    prepareForDocPendingTasks(docId: string) {
      this.getSavedListSettings();
      this.setItemInFiltersMap('keyword', docId);
      this.setItemInFiltersMap('status', 'open,in_progress');
    },

    saveListSettings() {
      const str = JSON.stringify(this.taskListSettingsMap, replacer);
      LocalStorage.set(this.tasks_list_settings_key, str);
    },

    setListSettings(key: string, value: any) {
      if (key === 'filters') {
        this.setFiltersMap(key, value);
      } else {
        this.taskListSettingsMap.set(key, value);
      }

      this.saveListSettings();
    },

    setFiltersMap(key: string, value: any) {
      this.taskfiltersMap = value;

      const hasAll = this.taskfiltersMap.has('all');
      if (hasAll && this.taskfiltersMap.size > 1) {
        this.taskfiltersMap.delete('all');
      }

      if (!hasAll && this.taskfiltersMap.size == 0) {
        this.taskfiltersMap.set('all', {
          label: 'all',
          value: 'all',
        });
      }

      this.taskListSettingsMap.set(key, this.taskfiltersMap);
    },

    setDefaultSettings() {
      this.taskListSettingsMap = new Map();
      this.taskfiltersMap = new Map();
      this.taskfiltersMap.set('all', {
        label: 'all',
        value: 'all',
      });

      this.page_size = 10;
      this.setListSettings('filters', this.taskfiltersMap);
      this.setListSettings('page_size', this.page_size);
      this.setDefaultSort();
    },

    setDefaultSort() {
      this.sort_by = 'created_on';
      this.sort_order = 'desc';
      this.setListSettings('sort_by', this.sort_by);
      this.setListSettings('sort_order', this.sort_order);
    },

    getSavedFiltersAsJson() {
      const excludeKeys = ['all'];
      const params = {} as dynamicObj;
      for (const [key, savedValue] of this.taskfiltersMap.entries()) {
        let value = savedValue;
        if (excludeKeys.includes(key)) {
          continue;
        }

        if (value.hasOwnProperty('value')) {
          value = value.value;
        }

        if (key == 'only_for_current_user') {
          if (value == 'all') {
            continue;
          }
        }

        if (key == 'status') {
          value = this.getStatusValue(value);
        }

        params[key] = value;
      }

      return params;
    },

    getStatusValue(value: any) {
      if (typeof value == 'string') {
        return value;
      }

      if (Array.isArray(value)) {
        const namesArray = value.map((item: any) =>
          typeof item === 'string' ? item : (item?.value as string),
        );
        return namesArray.join(',');
      }

      return '';
    },

    setOpenTaskCount(count: number) {
      this.open_task_count = Math.max(0, toPositiveInt(count, 0));
    },

    increaseOpenTaskCount(amount = 1) {
      this.open_task_count = this.open_task_count + amount;
    },

    decreaseOpenTaskCount(amount = 1) {
      this.open_task_count = Math.max(0, this.open_task_count - amount);
    },

    adjustCountForDoneTasks(doneCount: number) {
      if (this.currentViewStillCountsDoneTasks()) {
        return;
      }
      this.total_records = Math.max(0, this.total_records - doneCount);
      this.recalculateTotalPages();
    },

    currentViewStillCountsDoneTasks() {
      const activeStatuses = this.activeStatusFilter();
      return activeStatuses.length === 0 || activeStatuses.includes('done');
    },

    activeStatusFilter() {
      const status = this.taskfiltersMap.get('status');
      if (isUndefinedOrNull(status) || status === '') {
        return [] as string[];
      }
      if (typeof status === 'string') {
        return status.split(',').filter((s: string) => s.length > 0);
      }
      if (Array.isArray(status)) {
        return status
          .map((item: any) => (typeof item === 'string' ? item : item?.value))
          .filter((s: string) => s && s.length > 0);
      }
      return [] as string[];
    },

    recalculateTotalPages() {
      this.total_pages = Math.ceil(this.total_records / this.page_size);
    },

    async setPaginationSize(size: string) {
      this.page_size = toPositiveInt(size, 10);
      this.setListSettings('page_size', this.page_size);

      const settings_store = useSettingStore();
      await settings_store.setUserPreferences(
        this.list_size_key,
        this.page_size ? this.page_size : '10',
      );
    },

    setOrderBy(field: any, direction: string) {
      this.sort_by = field;
      this.sort_order = direction;
      this.setListSettings('sort_by', this.sort_by);
      this.setListSettings('sort_order', this.sort_order);
    },
    // END Search Utility Functions

    async isModuleOn() {
      this.is_module_on = false;
      const settings_store = useSettingStore();
      await settings_store.startSettingsFetch();
      const { user_settings } = settings_store;

      if (
        user_settings[tasks_notification_setting] &&
        user_settings[tasks_notification_setting] === true
      ) {
        this.is_module_on = true;
      }

      return this.is_module_on;
    },

    // Module Setting Functions

    // will be used from ACL store
    isHasAccess(row: any) {
      return (
        !this.isUserAdmin &&
        !idsEqual(row.assigned_to_user_id, this.userId) &&
        !Acl._isAssignedGroupMember(row)
      );
    },
  },
});
