import { api } from 'src/pages/APIs';
import AbstractApiService from '../abstractApiService';

export interface EDocTaxMappingUpsertPayload {
  tax_country: string;
  en16931_category: string;
  tax_rate?: string | number | null;
  erp_tax_code?: string | null;
  sub_org_id?: string | null;
  export_configuration_id?: number | null;
  is_active?: boolean;
  mapping_id?: string | null;
}

export default class EDocTaxMappingApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  public async upsertMapping(
    payload: EDocTaxMappingUpsertPayload,
  ): Promise<any> {
    const body = new FormData();
    body.append('tax_country', payload.tax_country);
    body.append('en16931_category', payload.en16931_category);
    if (
      payload.tax_rate !== null &&
      payload.tax_rate !== undefined &&
      payload.tax_rate !== ''
    ) {
      body.append('tax_rate', String(payload.tax_rate));
    }
    if (payload.erp_tax_code) {
      body.append('erp_tax_code', payload.erp_tax_code);
    }
    if (payload.sub_org_id) {
      body.append('sub_org_id', payload.sub_org_id);
    }
    if (
      payload.export_configuration_id !== null &&
      payload.export_configuration_id !== undefined
    ) {
      body.append(
        'export_configuration_id',
        String(payload.export_configuration_id),
      );
    }
    if (payload.is_active !== undefined) {
      body.append('is_active', String(payload.is_active));
    }
    if (payload.mapping_id) {
      body.append('mapping_id', payload.mapping_id);
    }

    return super.post(api.edoc_tax_mapping_upsert, body);
  }

  public async listMappings(): Promise<any> {
    return super.get(api.edoc_tax_mapping_list);
  }

  public async deleteMapping(mappingId: string): Promise<any> {
    return super.deleteWithoutOrgId(
      api.edoc_tax_mapping_delete + '/' + encodeURIComponent(mappingId),
    );
  }
}
