// Multi-Org Login, step 1 → step 2 handoff (SD 2860679170 §4.1, M1).
//
// When the password grant returns `org_selection_required` instead of a full
// token, Login.vue has NO full token to act on yet — only a short-lived,
// single-use `selection_token` (TTL ~5min server-side) plus the user's
// organisation list. That needs to survive a route navigation to
// /select-organisation (OrgPicker.vue) without ever touching LocalStorage
// (it must not outlive the tab, and must not be confused with a real,
// authenticated session). SessionStorage is exactly the right lifetime and
// matches how `active_org_id` is already stored (org_id_helper.ts).

import { SessionStorage } from 'quasar';
import type { MeOrganisationItem } from 'src/sdk/auth/models';

const STORAGE_KEY = 'org_selection_pending';

/** Shape of the org-selection-required response from POST /v2/oauth2/token (SD §5). */
export interface OrgSelectionRequiredResponse {
  org_selection_required: true;
  selection_token: string;
  organisations: MeOrganisationItem[];
}

/** Narrows an arbitrary login response to the org-selection-required variant. */
export function isOrgSelectionRequired(
  response: unknown,
): response is OrgSelectionRequiredResponse {
  const r = response as Partial<OrgSelectionRequiredResponse> | null | undefined;
  return (
    !!r &&
    r.org_selection_required === true &&
    typeof r.selection_token === 'string' &&
    Array.isArray(r.organisations)
  );
}

export interface OrgSelectionPending {
  selectionToken: string;
  organisations: MeOrganisationItem[];
  /** Route to continue to after select-org succeeds (mirrors Login.vue's `redirect` query param). */
  redirect: string;
  /** Mirrors Login.vue's `needsReloadForRegion` — a hard reload instead of router.push when the
   * auth-region dropdown selection differs from where the app currently points. */
  forceFullReload: boolean;
}

export function storeOrgSelectionPending(pending: OrgSelectionPending): void {
  SessionStorage.set(STORAGE_KEY, pending);
}

/** Reads and clears the pending selection in one step — single-use, same as the server-side token. */
export function takeOrgSelectionPending(): OrgSelectionPending | null {
  const pending = SessionStorage.getItem(STORAGE_KEY) as OrgSelectionPending | null;
  SessionStorage.remove(STORAGE_KEY);
  return pending ?? null;
}
